import XCTest

final class RoomTapTests: XCTestCase {
    let dir = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/RoomTap/"

    func dump(_ name: String, _ app: XCUIApplication) {
        try? app.debugDescription.write(toFile: dir + name + ".txt", atomically: true, encoding: .utf8)
    }

    func testOpenTeamStandupInfo() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        let hittable = NSPredicate(format: "label == 'Team Standup' AND isHittable == YES")
        let row = app.staticTexts.matching(hittable).firstMatch
        XCTAssertTrue(row.waitForExistence(timeout: 15))
        row.tap()
        Thread.sleep(forTimeInterval: 3)
        dump("room", app)
        let title = app.staticTexts.matching(hittable).firstMatch
        if title.waitForExistence(timeout: 5) {
            title.tap()
        } else {
            let btn = app.buttons.containing(NSPredicate(format: "label CONTAINS 'Team Standup'")).firstMatch
            XCTAssertTrue(btn.waitForExistence(timeout: 5))
            btn.tap()
        }
        Thread.sleep(forTimeInterval: 3)
        dump("info", app)
    }
}
EOF
